public void initializeEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() ==  dataEntityDataSourceStr(GUPRebateAgreementTypePricingComponentEntity, GUPPriceComponentCode))
    {
        _dataSourceCtx.setDataSaved(true);
        _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::None);
    }
    else if (_dataSourceCtx.name() ==  dataEntityDataSourceStr(GUPRebateAgreementTypePricingComponentEntity, GUPRebateAgreementTypePricingComponent))
    {
        if (_dataSourceCtx.getDatabaseOperation() != DataEntityDatabaseOperation::Insert)
        {
            _dataSourceCtx.setDataSaved(true);
            _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::None);
        }
    }
}

public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPRebateAgreementTypePricingComponentEntity, GUPRebateAgreementTypePricingComponent))
    {
        GUPPriceComponentCode componentCode = GUPPriceComponentCode::findByName(this.ComponentCodeName);
        if (!componentCode || componentCode.PriceComponent != GUPPriceComponent::RebateManagement)
        {
            throw error(strfmt("@GlobalUnifiedPricing:RebateAgreementTypeCannotBeUpdatedWithoutQulifiedComponentCode", this.ComponentCodeName));
        }

        GUPRebateAgreementType rebateAgreementType = GUPRebateAgreementType::findByName(this.TypeName);
        if (!rebateAgreementType)
        {
            throw error(strfmt("@GlobalUnifiedPricing:RebateAgreementTypeCannotBeUpdatedWithoutAgreementType", this.TypeName));
        }
    }
    super(_entityCtx, _dataSourceCtx);
}
